def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3: continue
            if r-2 >= 0:
                for x in range(max(0,c-2), min(w,c+3)): out[r-2][x] = 5
            for y in (r-1,r,r+1):
                if 0 <= y < h:
                    if c-2 >= 0: out[y][c-2] = 2
                    if c+2 < w: out[y][c+2] = 2
            if 0 <= r-1 < h: out[r-1][c] = 5
            if 0 <= r+2 < h:
                for x in range(w): out[r+2][x] = 2
                for x in range(max(0,c-2), min(w,c+3)): out[r+2][x] = 8
    return out
